chunk.argumentsDelta:
{"file_path":"src/positions.js","content":"/**
 * Precomputes the line and column of every code point in the input, per the
 * tab-stop and newline rules the scanner uses to report positions.
 */

export function computePositions(chars) {
  const positions = new Array(chars.length)
  let line = 1
  let col = 1
  for (let i = 0; i < chars.length; i++) {
    positions[i] = { line, col }
    const c = chars[i]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
  }
  return positions
}
"}

