{"file_path":"src/lex-error.js","content":"/**
 * Raised by the scanner when the input does not follow the grammar. Carries
 * the position the error is reported at and a reason text.
 */

export class LexError extends Error {
  constructor(pos, reason) {
    super(`${pos.line}:${pos.col}: ${reason}`)
    this.pos = pos
    this.reason = reason
  }
}
"}

