chunk.argumentsDelta:
{"file_path":"src/char-classes.js","content":"/**
 * Character classifications shared by the identifier, number and string
 * scanners.
 */

export const isDecDigit = (c) => c >= '0' && c <= '9'
export const isHexDigit = (c) => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
export const isBinDigit = (c) => c === '0' || c === '1'
export const isOctDigit = (c) => c >= '0' && c <= '7'
export const isLetter = (c) => /\p{L}/u.test(c)
export const isIdStart = (c) => isLetter(c) || c === '_'
export const isIdContinue = (c) => isLetter(c) || isDecDigit(c) || c === '_'

// A letter, digit or underscore trailing a number that its own grammar did
// not consume; such a character always makes the number an error.
export const isNumberTrailer = (c) => isLetter(c) || isDecDigit(c) || c === '_'
"}

