{"file_path":"src/scan-number.js","content":"import { LexError } from './lex-error.js'
import { isDecDigit, isHexDigit, isBinDigit, isOctDigit, isNumberTrailer } from './char-classes.js'

/**
 * Scans a digit run starting at `i` (already known to be a digit of the
 * given class), consuming a single `_` wherever it sits between two digits
 * of the run. Returns the index just past the run.
 */
function scanDigitRun(chars, i, len, isDigit) {
  let j = i + 1
  while (j < len) {
    if (isDigit(chars[j])) {
      j++
    } else if (chars[j] === '_' && j + 1 < len && isDigit(chars[j + 1])) {
      j += 2
    } else {
      break
    }
  }
  return j
}

/**
 * Scans a `number` token starting at `i`, where `chars[i]` is already known
 * to be a decimal digit. Throws `LexError` for malformed numbers, per the
 * spec's "invalid number" rule.
 */
export function scanNumber(chars, positions, i, len) {
  const start = i
  const pos = positions[i]
  let end
  let valid = true

  const c1 = chars[i]
  const c2 = i + 1 < len ? chars[i + 1] : null
  let prefixDigitClass = null
  if (c1 === '0' && (c2 === 'x' || c2 === 'X')) prefixDigitClass = isHexDigit
  else if (c1 === '0' && (c2 === 'b' || c2 === 'B')) prefixDigitClass = isBinDigit
  else if (c1 === '0' && (c2 === 'o' || c2 === 'O')) prefixDigitClass = isOctDigit

  if (prefixDigitClass) {
    const i2 = i + 2
    if (i2 < len && prefixDigitClass(chars[i2])) {
      end = scanDigitRun(chars, i2, len, prefixDigitClass)
    } else {
      end = i2
      valid = false
    }
  } else {
    end = scanDigitRun(chars, i, len, isDecDigit)
    if (end < len && chars[end] === '.' && end + 1 < len && isDecDigit(chars[end + 1])) {
      end = scanDigitRun(chars, end + 1, len, isDecDigit)
    }
    if (end < len && (chars[end] === 'e' || chars[end] === 'E')) {
      let j = end + 1
      if (j < len && (chars[j] === '+' || chars[j] === '-')) j++
      if (j < len && isDecDigit(chars[j])) {
        end = scanDigitRun(chars, j, len, isDecDigit)
      }
    }
  }

  let j = end
  while (j < len && isNumberTrailer(chars[j])) j++

  if (!valid || j > end) {
    const text = chars.slice(start, j).join('')
    throw new LexError(pos, `invalid number ${text}`)
  }

  const text = chars.slice(start, end).join('')
  return { kind: 'number', pos, text, end }
}
"}

