{"file_path":"src/scan-string.js","content":"import { LexError } from './lex-error.js'
import { isHexDigit } from './char-classes.js'

/**
 * Scans a `string` token starting at the opening `"` at `i`. Returns the
 * decoded value (escapes resolved) and the index just past the closing
 * quote.
 */
export function scanString(chars, positions, i, len) {
  const pos = positions[i]
  let j = i + 1
  let value = ''

  for (;;) {
    if (j >= len) throw new LexError(pos, 'unterminated string')
    const c = chars[j]
    if (c === '"') {
      j++
      break
    }
    if (c === '\n') throw new LexError(positions[j], 'newline in string')
    if (c === '\\') {
      const escPos = positions[j]
      j++
      if (j >= len) throw new LexError(pos, 'unterminated string')
      const ec = chars[j]
      if (ec === 'n') {
        value += '\n'
        j++
      } else if (ec === 't') {
        value += '\t'
        j++
      } else if (ec === 'r') {
        value += '\r'
        j++
      } else if (ec === '\\') {
        value += '\\'
        j++
      } else if (ec === '"') {
        value += '"'
        j++
      } else if (ec === '0') {
        value += '\0'
        j++
      } else if (ec === 'x') {
        const h1 = j + 1 < len ? chars[j + 1] : null
        const h2 = j + 2 < len ? chars[j + 2] : null
        if (h1 !== null && h2 !== null && isHexDigit(h1) && isHexDigit(h2)) {
          value += String.fromCodePoint(parseInt(h1 + h2, 16))
          j += 3
        } else {
          throw new LexError(escPos, 'invalid escape \\x')
        }
      } else if (ec === 'u') {
        if (j + 1 < len && chars[j + 1] === '{') {
          let k = j + 2
          let hex = ''
          while (k < len && chars[k] !== '}' && isHexDigit(chars[k])) {
            hex += chars[k]
            k++
          }
          const codePoint = hex.length > 0 ? parseInt(hex, 16) : NaN
          if (hex.length > 0 && k < len && chars[k] === '}' && codePoint <= 0x10ffff) {
            value += String.fromCodePoint(codePoint)
            j = k + 1
          } else {
            throw new LexError(escPos, 'invalid escape \\u')
          }
        } else {
          throw new LexError(escPos, 'invalid escape \\u')
        }
      } else {
        throw new LexError(escPos, `invalid escape \\${ec}`)
      }
    } else {
      value += c
      j++
    }
  }

  return { kind: 'string', pos, value, end: j }
}

/**
 * Scans a `rawstring` token starting at the `r` at `i`. Its position is
 * that of the `r`, and it carries no escapes.
 */
export function scanRawString(chars, positions, i, len) {
  const pos = positions[i]
  let j = i + 2
  while (j < len && chars[j] !== '"') j++
  if (j >= len) throw new LexError(pos, 'unterminated string')
  const value = chars.slice(i + 2, j).join('')
  return { kind: 'rawstring', pos, value, end: j + 1 }
}
"}

